    .Call(`_BioGA_initialize_population_cpp`, genomic_data, population_size, seed, clusters, representation)
}

#' Mutate offspring with an adaptive rate
#'
#' The mutation rate increases linearly with the generation index. Real-coded
#' mode applies Gaussian perturbation; binary mode flips selection bits.
#' When a gene network is supplied, the perturbation of each gene is damped by
#' its relative connectivity (degree), so network hubs change less.
#'
#' @param offspring Numeric matrix of offspring.
#' @param mutation_rate Base probability of mutation.
#' @param iteration Current GA iteration.
#' @param max_iterations Maximum number of GA iterations.
#' @param network Optional symmetric adjacency matrix
#' (rows: genes, columns: genes).
#' @param representation Either `"real"` or `"binary"`.
#' @return Numeric matrix of mutated offspring.
#' @family mutation
#' @seealso [initialize_population_cpp()], [evaluate_fitness_cpp()],
#'   [selection_cpp()], [crossover_cpp()], [replacement_cpp()],
#'   [bioga_main_cpp()]
#' @examples
#' genomic_data <- matrix(rnorm(100), nrow = 10, ncol = 10)
#' population <- BioGA::initialize_population_cpp(genomic_data, population_size = 5)
#' fitness <- BioGA::evaluate_fitness_cpp(genomic_data, population, c(1.0, 0.5))
#' parents <- BioGA::selection_cpp(population, fitness, num_parents = 2)
#' offspring <- BioGA::crossover_cpp(parents, offspring_size = 2)
#' BioGA::mutation_cpp(offspring, mutation_rate = 0.1, iteration = 1,
#'   max_iterations = 100)
#' @export
mutation_cpp <- function(offspring, mutation_rate, iteration, max_iterations, network = NULL, representation = "real") {
    .Call(`_BioGA_mutation_cpp`, offspring, mutation_rate, iteration, max_iterations, network, representation)
}

#' Build the next population with NSGA-II environmental selection
#'
#' The `num_to_replace` best offspring (by NSGA-II rank and crowding distance)
#' replace the lowest-quality parents, keeping the best `population_size -
#' num_to_replace` parents. This preserves elitism while letting offspring
#' enter only on merit. If `num_to_replace <= 0` the population is unchanged.
#'
#' @param population Numeric matrix of current individuals.
#' @param offspring Numeric matrix of offspring.
#' @param fitness Numeric matrix of current population fitness scores.
#' @param offspring_fitness Numeric matrix of offspring fitness scores.
#' @param num_to_replace Maximum number of offspring to admit.
#' @return Numeric matrix of the updated population.
#' @family replacement
#' @seealso [initialize_population_cpp()], [evaluate_fitness_cpp()],
#'   [selection_cpp()], [crossover_cpp()], [mutation_cpp()],
#'   [bioga_main_cpp()]
#' @examples
#' genomic_data <- matrix(rnorm(100), nrow = 10, ncol = 10)
#' population <- BioGA::initialize_population_cpp(genomic_data, population_size = 5)
#' fitness <- BioGA::evaluate_fitness_cpp(genomic_data, population, c(1.0, 0.5))
#' offspring <- population
#' offspring_fitness <- fitness
#' BioGA::replacement_cpp(population, offspring, fitness, offspring_fitness,
#'   num_to_replace = 1)
#' @export
replacement_cpp <- function(population, offspring, fitness, offspring_fitness, num_to_replace) {
    .Call(`_BioGA_replacement_cpp`, population, offspring, fitness, offspring_fitness, num_to_replace)
}

